// Query with time range options
fetch logs, from: now() - 24h, to: now() - 12h
| summarize {count = count()}, by: {loglevel}
| sort count desc

// Filter using in() for multiple values
fetch logs, from: now() - 1h
| filter in(loglevel, {"ERROR", "WARN", "INFO"})
| summarize {count = count()}, by: {loglevel}
| sort count desc

// Exclude patterns with NOT
// status == "ERROR" covers every error-class level (ERROR, SEVERE, CRITICAL, FATAL, …);
// loglevel == "ERROR" alone misses SEVERE and the rest
fetch logs, from: now() - 1h
| filter status == "ERROR"
| filter NOT matchesPhrase(content, "health")
| filter NOT matchesPhrase(content, "heartbeat")
| fieldsAdd content_preview = substring(content, from: 0, to: 100)
| summarize {count = count()}, by: {content_preview}
| sort count desc
| limit 10

// Add computed fields
fetch logs, from: now() - 1h
| filter status == "ERROR"
| fieldsAdd severity = if(contains(content, "critical"), "CRITICAL", 
else: if(contains(content, "fatal"), "FATAL",
else: loglevel))
| fieldsAdd content_length = stringLength(content)
| fields timestamp, severity, content_length, dt.entity.host
| limit 20

// Parse log level from content (e.g., "[ERROR] message")
fetch logs, from: now() - 1h
| filter startsWith(content, "[")
| parse content, "'[' LD:parsed_level ']'"
// keep only supported loglevel values — bracketed timestamps and message fragments are not levels
| fieldsAdd parsed_level = upper(parsed_level)
| filter in(parsed_level, {"EMERGENCY", "ALERT", "CRITICAL", "SEVERE", "ERROR", "FATAL", "WARN", "NOTICE", "INFO", "DEBUG", "TRACE"})
| summarize {count = count()}, by: {parsed_level}
| sort count desc
| limit 10

// Parse HTTP-style logs
// Example: GET /api/users 200 45ms -> GET, /api/users, 200
// Returns rows only for single-spaced lines of this exact shape; the range filter drops counters in the status position
fetch logs, from: now() - 1h
| filter contains(content, "GET") OR contains(content, "POST")
| parse content, "[A-Z]+:method ' ' NSPACE:path ' ' INT:status_code ' '"
| filter status_code >= 100 and status_code <= 599
| summarize {count = count()}, by: {method, status_code}
| sort count desc
| limit 15

// Parse key-value pairs
// Example: "user=john action=login status=success"
// parseAll returns every user= value in the line (parse would return only one);
// the !<< lookbehind stops "superuser=root" or "service_user=x" matching as user=
fetch logs, from: now() - 1h
| fieldsAdd usernames = parseAll(content, "!<<[A-Za-z0-9_] 'user=' [A-Za-z0-9._@-]+:username")
| filter arraySize(usernames) > 0
| expand username = usernames
| summarize {count = count()}, by: {username}
| sort count desc
| limit 10

// Parse IP addresses from logs
fetch logs, from: now() - 1h
// parseAll finds every IP anywhere in the line; parse would only match one at the very start
// IPADDR also matches IPv4-shaped version strings (rv:1.9.2.20) and IPv6 fragments (::0000);
// OPLOGS-08 §3 shows a bounded IPv4 pattern for classification
| fieldsAdd client_ip = parseAll(content, "IPADDR:ip")
| filter arraySize(client_ip) > 0
| expand client_ip
| summarize {count = count()}, by: {client_ip}
| sort count desc
| limit 15

// Check for null values
fetch logs, from: now() - 1h
| summarize {
total = count(),
with_host = countIf(isNotNull(dt.entity.host)),
without_host = countIf(isNull(dt.entity.host)),
with_namespace = countIf(isNotNull(k8s.namespace.name)),
without_namespace = countIf(isNull(k8s.namespace.name))
}

// Use coalesce for default values
// coalesce returns the first non-null argument: the workload name, else the namespace, else "UNKNOWN".
// (coalesce(loglevel, …) would never fall back: loglevel is never null, and missing levels arrive as "NONE".)
fetch logs, from: now() - 1h
| fieldsAdd owner = coalesce(k8s.workload.name, k8s.namespace.name, "UNKNOWN")
| summarize {count = count()}, by: {owner}
| sort count desc
| limit 15

// Parse exception patterns
// Split the record into whitespace-separated tokens (splitByPattern with SPACE also splits on line breaks) and keep the ones that end in "Exception".
// A pattern like "LD:exception_type 'Exception'" anchors at the start of the line, so it
// captures the whole prefix ("2026-10-02 ERROR c.e.Svc - java.lang.NullPointer") instead
// of the class name; DPL does not backtrack, so a greedy word matcher cannot stop before
// the literal "Exception" either.
fetch logs, from: now() - 24h
| filter contains(content, "Exception")
| fieldsAdd token = splitByPattern(content, "SPACE")
| expand token
| filter endsWith(token, "Exception") OR endsWith(token, "Exception:")
| fieldsAdd exception_type = replaceString(token, ":", "")
| summarize {count = count()}, by: {exception_type}
| sort count desc
| limit 15

// Parse with optional fields
// Matches "error code=123" or "... error code=123 message=failed" anywhere in the line
// (DATA? lets the pattern start mid-line; parse otherwise anchors at the start)
fetch logs, from: now() - 1h
| filter contains(content, "error")
| parse content, "DATA? 'error' SPACE 'code=' INT:error_code (SPACE 'message=' LD:error_msg)?"
| filter isNotNull(error_code)
| summarize {count = count()}, by: {error_code}
| sort count desc
| limit 10

// Parse alternative formats
// Matches "user=john" or "username=john" anywhere in the line, every occurrence (parseAll);
// the character class stops at the first character outside it, so "user=jdoe," yields "jdoe"
// (a trailing LD would take the rest of the line), and the !<< lookbehind skips "superuser=root"
fetch logs, from: now() - 1h
| fieldsAdd user_values = parseAll(content, "!<<[A-Za-z0-9_] ('user='|'username=') [A-Za-z0-9._@-]+:user_value")
| filter arraySize(user_values) > 0
| expand user_value = user_values
| summarize {count = count()}, by: {user_value}
| sort count desc
| limit 10
